class Solution {
public:
    int validSubarraySize(std::vector<int>& nums, int threshold) {
        int n = nums.size();
        std::vector<int> left(n, -1), right(n, n);
        std::vector<int> stk;
        for (int i = 0; i < n; ++i) {
            while (!stk.empty() && nums[stk.back()] >= nums[i]) stk.pop_back();
            if (!stk.empty()) left[i] = stk.back();
            stk.push_back(i);
        }
        stk.clear();
        for (int i = n - 1; i >= 0; --i) {
            while (!stk.empty() && nums[stk.back()] >= nums[i]) stk.pop_back();
            if (!stk.empty()) right[i] = stk.back();
            stk.push_back(i);
        }
        for (int i = 0; i < n; ++i) {
            int k = right[i] - left[i] - 1;
            if ((long long)nums[i] * k > threshold) return k;
        }
        return -1;
    }
};

class Solution {
    public int validSubarraySize(int[] nums, int threshold) {
        int n = nums.length;
        int[] left = new int[n];
        int[] right = new int[n];
        java.util.Arrays.fill(left, -1);
        java.util.Arrays.fill(right, n);
        int[] stk = new int[n];
        int top = -1;
        for (int i = 0; i < n; ++i) {
            while (top >= 0 && nums[stk[top]] >= nums[i]) top--;
            if (top >= 0) left[i] = stk[top];
            stk[++top] = i;
        }
        top = -1;
        for (int i = n - 1; i >= 0; --i) {
            while (top >= 0 && nums[stk[top]] >= nums[i]) top--;
            if (top >= 0) right[i] = stk[top];
            stk[++top] = i;
        }
        for (int i = 0; i < n; ++i) {
            int k = right[i] - left[i] - 1;
            if ((long) nums[i] * k > threshold) return k;
        }
        return -1;
    }
}

