    const left = new Array(n).fill(-1);
    const right = new Array(n).fill(n);
    let stk = [];
    for (let i = 0; i < n; ++i) {
        while (stk.length && nums[stk[stk.length - 1]] >= nums[i]) stk.pop();
        if (stk.length) left[i] = stk[stk.length - 1];
        stk.push(i);
    }
    stk = [];
    for (let i = n - 1; i >= 0; --i) {
        while (stk.length && nums[stk[stk.length - 1]] >= nums[i]) stk.pop();
        if (stk.length) right[i] = stk[stk.length - 1];
        stk.push(i);
    }
    for (let i = 0; i < n; ++i) {
        const k = right[i] - left[i] - 1;
        if (nums[i] * k > threshold) return k;
